&#47;&#47; 调用 getUserProfile
err := getUserProfile(userID)
if err != nil {
    if errors.Is(err, sql.ErrNoRows) {
        return ErrUserNotFound
    }
    &#47;&#47; 其他数据库错误会继续向下处理
}

&#47;&#47; 调用 calculateScore
err = calculateScore(profile)
if err != nil {
    var invalidProfileErr *validation.ErrInvalidProfile
    if errors.As(err, &amp;invalidProfileErr) {
        log.Printf(&quot;Validation error: %v&quot;, invalidProfileErr)
        return ErrProcessingFailed
    }
    &#47;&#47; 其他错误继续处理
}

&#47;&#47; 调用 updateAnalytics
err = updateAnalytics(userID, score)
if err != nil {
    var tempErr interface{ Temporary() bool }
    if errors.As(err, &amp;tempErr) &amp;&amp; tempErr.Temporary() {
        &#47;&#47; 重试一次
        retryErr := updateAnalytics(userID, score)
        if retryErr != nil {
            return fmt.Errorf(&quot;failed to update analytics after retry: %w&quot;, retryErr)
        }
    } else {
        &#47;&#47; 非临时网络错误，直接返回
        return fmt.Errorf(&quot;failed to update analytics: %w&quot;, err)
    }
}

&#47;&#47; 其他未知错误统一包装处理
return fmt.Errorf(&quot;failed to process user data for id %d: %w&quot;, userID, err)
